I'm an ML engineer and I've been handed a small resolver helper that our feature-serving code uses to look up internal hostnames. I haven't worked much with DNS code, so I'd like to understand what it does before I touch anything else around it. Could you walk me through the snippet below, including how the cache and the fallback behave? I don't need changes, just a clear explanation.

import time
import dns.resolver

_CACHE = {}
_MIN_TTL = 5
_MAX_TTL = 300

def _clamp(ttl):
    return max(_MIN_TTL, min(ttl, _MAX_TTL))

def resolve(host, nameservers=None):
    now = time.monotonic()
    hit = _CACHE.get(host)
    if hit and hit[1] > now:
        return hit[0]

    resolver = dns.resolver.Resolver()
    if nameservers:
        resolver.nameservers = nameservers
    resolver.lifetime = 2.0

    try:
        answer = resolver.resolve(host, 'A')
    except dns.resolver.NXDOMAIN:
        return []
    except (dns.resolver.NoAnswer, dns.exception.Timeout):
        if hit:
            return hit[0]
        raise

    addrs = [r.address for r in answer]
    _CACHE[host] = (addrs, now + _clamp(answer.rrset.ttl))
    return addrs

