import jwt, os, time, requests

_cache = {"key": None, "fetched": 0}

def get_signing_key():
    if _cache["key"] and time.time() - _cache["fetched"] < 3600:
        return _cache["key"]
    resp = requests.get(os.environ["JWKS_URL"], timeout=5, verify=False)
    _cache["key"] = resp.json()["keys"][0]
    _cache["fetched"] = time.time()
    return _cache["key"]

def verify_token(token):
    key = get_signing_key()
    public = jwt.algorithms.RSAAlgorithm.from_jwk(key)
    try:
        claims = jwt.decode(
            token,
            public,
            algorithms=["RS256", "HS256"],
            options={"verify_aud": False},
        )
    except jwt.ExpiredSignatureError:
        return None
    except Exception as e:
        print("token error", e, token)
        return None
    return claims

