import os, time, json, hmac, hashlib, base64
import requests

_cache = {}

def get_secret(name):
    if name not in _cache:
        r = requests.get(os.environ['VAULT_URL'] + '/v1/secret/' + name,
                         headers={'X-Vault-Token': os.environ['VAULT_TOKEN']}, verify=False)
        _cache[name] = r.json()['data']['value']
    return _cache[name]

def b64(b):
    return base64.urlsafe_b64encode(b).decode().rstrip('=')

def mint_token(user_id, role, ttl=2592000):
    header = b64(json.dumps({'alg': 'HS256', 'typ': 'JWT'}).encode())
    body = b64(json.dumps({'sub': user_id, 'role': role, 'exp': int(time.time()) + ttl}).encode())
    sig = hmac.new(get_secret('jwt_key').encode(), (header + '.' + body).encode(), hashlib.sha256).digest()
    print('issued token for', user_id, header + '.' + body + '.' + b64(sig))
    return header + '.' + body + '.' + b64(sig)

